insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-artificial-intelligence-trivia',
  'Artificial Intelligence Trivia: From Turing to Transformers',
  'Eight questions on the milestones of artificial intelligence: Turing, Dartmouth, Deep Blue, AlphaGo and the transformer era.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"Who proposed the ''imitation game'' as a test of machine intelligence in 1950?","options":[{"id":"a","text":"Alan Turing","is_correct":true},{"id":"b","text":"John von Neumann","is_correct":false},{"id":"c","text":"Claude Shannon","is_correct":false},{"id":"d","text":"Norbert Wiener","is_correct":false}],"explanation":"Turing opened his 1950 paper ''Computing Machinery and Intelligence'' with the imitation game."},{"id":"q2","question":"Where was the term ''artificial intelligence'' coined in 1956?","options":[{"id":"a","text":"MIT","is_correct":false},{"id":"b","text":"Stanford University","is_correct":false},{"id":"c","text":"Dartmouth College","is_correct":true},{"id":"d","text":"Bell Labs","is_correct":false}],"explanation":"John McCarthy used it in the proposal for the Dartmouth summer research workshop."},{"id":"q3","question":"Which IBM computer defeated world chess champion Garry Kasparov in 1997?","options":[{"id":"a","text":"Watson","is_correct":false},{"id":"b","text":"Deep Blue","is_correct":true},{"id":"c","text":"Deep Thought","is_correct":false},{"id":"d","text":"AlphaZero","is_correct":false}],"explanation":"Deep Blue won the six-game rematch 3.5–2.5 in May 1997."},{"id":"q4","question":"Which IBM system won the quiz show Jeopardy! in 2011?","options":[{"id":"a","text":"Watson","is_correct":true},{"id":"b","text":"Deep Blue","is_correct":false},{"id":"c","text":"ELIZA","is_correct":false},{"id":"d","text":"Siri","is_correct":false}],"explanation":"Watson beat champions Ken Jennings and Brad Rutter in a televised match."},{"id":"q5","question":"Which DeepMind program beat Go champion Lee Sedol in 2016?","options":[{"id":"a","text":"Stockfish","is_correct":false},{"id":"b","text":"MuZero","is_correct":false},{"id":"c","text":"AlphaZero","is_correct":false},{"id":"d","text":"AlphaGo","is_correct":true}],"explanation":"AlphaGo won the five-game match in Seoul 4–1, a milestone for Go, long thought beyond computers."},{"id":"q6","question":"Which 2017 paper introduced the transformer architecture behind modern chatbots?","options":[{"id":"a","text":"''Attention Is All You Need''","is_correct":true},{"id":"b","text":"''Generative Adversarial Nets''","is_correct":false},{"id":"c","text":"''ImageNet Classification with Deep CNNs''","is_correct":false},{"id":"d","text":"''Playing Atari with Deep Reinforcement Learning''","is_correct":false}],"explanation":"Eight Google researchers proposed the transformer, the basis of GPT and other language models."},{"id":"q7","question":"How many parameters did OpenAI''s GPT-3 have when it was released in 2020?","options":[{"id":"a","text":"1.5 billion","is_correct":false},{"id":"b","text":"17 billion","is_correct":false},{"id":"c","text":"175 billion","is_correct":true},{"id":"d","text":"1.5 trillion","is_correct":false}],"explanation":"GPT-3''s largest version had 175 billion parameters, about 100 times GPT-2''s."},{"id":"q8","question":"Which three researchers shared the 2018 Turing Award for their work on deep learning?","options":[{"id":"a","text":"Demis Hassabis, Shane Legg and Mustafa Suleyman","is_correct":false},{"id":"b","text":"Geoffrey Hinton, Yann LeCun and Yoshua Bengio","is_correct":true},{"id":"c","text":"Fei-Fei Li, Andrew Ng and Sebastian Thrun","is_correct":false},{"id":"d","text":"Sam Altman, Greg Brockman and Ilya Sutskever","is_correct":false}],"explanation":"The ACM honoured the trio sometimes called the ''godfathers of deep learning''."}]'::jsonb,
  null,
  array['technology', 'trivia', 'artificial intelligence', 'ai']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
