values (
  'es-trivia-inteligencia-artificial',
  'Trivia de inteligencia artificial: de Turing a los transformers',
  'Ocho preguntas sobre los hitos de la inteligencia artificial: Turing, Dartmouth, Deep Blue, AlphaGo y la era transformer.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"¿Quién propuso el ''juego de imitación'' como prueba de inteligencia en una máquina en 1950?","options":[{"id":"a","text":"Alan Turing","is_correct":true},{"id":"b","text":"John von Neumann","is_correct":false},{"id":"c","text":"Claude Shannon","is_correct":false},{"id":"d","text":"Norbert Wiener","is_correct":false}],"explanation":"Turing abrió su artículo de 1950 ''Computing Machinery and Intelligence'' con el juego de imitación."},{"id":"q2","question":"¿Dónde se acuñó el término ''inteligencia artificial'' en 1956?","options":[{"id":"a","text":"MIT","is_correct":false},{"id":"b","text":"Universidad de Stanford","is_correct":false},{"id":"c","text":"Dartmouth College","is_correct":true},{"id":"d","text":"Laboratorios Bell","is_correct":false}],"explanation":"John McCarthy lo usó en la propuesta del taller de verano de Dartmouth."},{"id":"q3","question":"¿Qué computadora de IBM venció al campeón mundial de ajedrez Garry Kasparov en 1997?","options":[{"id":"a","text":"Watson","is_correct":false},{"id":"b","text":"Deep Blue","is_correct":true},{"id":"c","text":"Deep Thought","is_correct":false},{"id":"d","text":"AlphaZero","is_correct":false}],"explanation":"Deep Blue ganó la revancha de seis partidas 3,5–2,5 en mayo de 1997."},{"id":"q4","question":"¿Qué sistema de IBM ganó el concurso televisivo Jeopardy! en 2011?","options":[{"id":"a","text":"Watson","is_correct":true},{"id":"b","text":"Deep Blue","is_correct":false},{"id":"c","text":"ELIZA","is_correct":false},{"id":"d","text":"Siri","is_correct":false}],"explanation":"Watson derrotó a los campeones Ken Jennings y Brad Rutter en un duelo televisado."},{"id":"q5","question":"¿Qué programa de DeepMind venció al campeón de Go Lee Sedol en 2016?","options":[{"id":"a","text":"Stockfish","is_correct":false},{"id":"b","text":"MuZero","is_correct":false},{"id":"c","text":"AlphaZero","is_correct":false},{"id":"d","text":"AlphaGo","is_correct":true}],"explanation":"AlphaGo ganó la serie de cinco partidas en Seúl por 4–1, un hito en un juego que se creía fuera del alcance de las máquinas."},{"id":"q6","question":"¿Qué artículo de 2017 introdujo la arquitectura transformer detrás de los chatbots actuales?","options":[{"id":"a","text":"''Attention Is All You Need''","is_correct":true},{"id":"b","text":"''Generative Adversarial Nets''","is_correct":false},{"id":"c","text":"''ImageNet Classification with Deep CNNs''","is_correct":false},{"id":"d","text":"''Playing Atari with Deep Reinforcement Learning''","is_correct":false}],"explanation":"Ocho investigadores de Google propusieron el transformer, la base de GPT y otros modelos de lenguaje."},{"id":"q7","question":"¿Cuántos parámetros tenía GPT-3 de OpenAI cuando se lanzó en 2020?","options":[{"id":"a","text":"1.500 millones","is_correct":false},{"id":"b","text":"17.000 millones","is_correct":false},{"id":"c","text":"175.000 millones","is_correct":true},{"id":"d","text":"1,5 billones","is_correct":false}],"explanation":"La versión más grande de GPT-3 tenía 175.000 millones de parámetros, unas 100 veces más que GPT-2."},{"id":"q8","question":"¿Qué tres investigadores compartieron el Premio Turing 2018 por el aprendizaje profundo?","options":[{"id":"a","text":"Demis Hassabis, Shane Legg y Mustafa Suleyman","is_correct":false},{"id":"b","text":"Geoffrey Hinton, Yann LeCun y Yoshua Bengio","is_correct":true},{"id":"c","text":"Fei-Fei Li, Andrew Ng y Sebastian Thrun","is_correct":false},{"id":"d","text":"Sam Altman, Greg Brockman e Ilya Sutskever","is_correct":false}],"explanation":"La ACM distinguió al trío a veces llamado los ''padrinos del aprendizaje profundo''."}]'::jsonb,
  null,
  array['tecnología', 'trivia', 'inteligencia artificial', 'ia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
