insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-robotics-trivia',
  'Robotics Trivia: From Unimate to Mars Rovers',
  'Eight questions on the machines that moved robotics forward, from the first industrial arm to the rovers on Mars.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"Which machine, installed at a General Motors plant in 1961, was the first industrial robot?","options":[{"id":"a","text":"PUMA","is_correct":false},{"id":"b","text":"Unimate","is_correct":true},{"id":"c","text":"Shakey","is_correct":false},{"id":"d","text":"AIBO","is_correct":false}],"explanation":"Unimate lifted hot die-cast parts on the assembly line at the GM plant in Ewing, New Jersey."},{"id":"q2","question":"In which 1920 play did the word ''robot'' first appear?","options":[{"id":"a","text":"Metropolis","is_correct":false},{"id":"b","text":"The War of the Worlds","is_correct":false},{"id":"c","text":"R.U.R. (Rossum''s Universal Robots)","is_correct":true},{"id":"d","text":"Frankenstein","is_correct":false}],"explanation":"Karel Čapek''s play took the name from ''robota'', Czech for forced labour."},{"id":"q3","question":"Which 1942 Isaac Asimov short story introduced the Three Laws of Robotics?","options":[{"id":"a","text":"''Runaround''","is_correct":true},{"id":"b","text":"''Robbie''","is_correct":false},{"id":"c","text":"''The Caves of Steel''","is_correct":false},{"id":"d","text":"''The Evitable Conflict''","is_correct":false}],"explanation":"Asimov stated the three laws explicitly in ''Runaround'', later collected in ''I, Robot''."},{"id":"q4","question":"Which Honda humanoid robot, unveiled in 2000, could walk, run and climb stairs?","options":[{"id":"a","text":"Atlas","is_correct":false},{"id":"b","text":"Pepper","is_correct":false},{"id":"c","text":"QRIO","is_correct":false},{"id":"d","text":"ASIMO","is_correct":true}],"explanation":"ASIMO, the result of more than a decade of Honda research, demonstrated on two legs."},{"id":"q5","question":"Which NASA rover has been exploring Gale crater on Mars since 2012?","options":[{"id":"a","text":"Curiosity","is_correct":true},{"id":"b","text":"Sojourner","is_correct":false},{"id":"c","text":"Opportunity","is_correct":false},{"id":"d","text":"Perseverance","is_correct":false}],"explanation":"Curiosity landed in August 2012 with the skycrane manoeuvre and still operates."},{"id":"q6","question":"Which rover landed on Mars in 2021 carrying the Ingenuity helicopter?","options":[{"id":"a","text":"Spirit","is_correct":false},{"id":"b","text":"Perseverance","is_correct":true},{"id":"c","text":"Curiosity","is_correct":false},{"id":"d","text":"Sojourner","is_correct":false}],"explanation":"Perseverance touched down in Jezero crater; Ingenuity made the first powered flight on another planet."},{"id":"q7","question":"Which robotic system, cleared by the FDA in 2000, assists surgeons in the operating room?","options":[{"id":"a","text":"AESOP","is_correct":false},{"id":"b","text":"ZEUS","is_correct":false},{"id":"c","text":"da Vinci Surgical System","is_correct":true},{"id":"d","text":"Mako","is_correct":false}],"explanation":"The da Vinci system translates the surgeon''s hand movements into precise instrument motion."},{"id":"q8","question":"Which iRobot vacuum robot, launched in 2002, became a household name?","options":[{"id":"a","text":"Roomba","is_correct":true},{"id":"b","text":"Scooba","is_correct":false},{"id":"c","text":"Trilobite","is_correct":false},{"id":"d","text":"Neato","is_correct":false}],"explanation":"Roomba brought domestic robots to millions of homes and sold over a million units in its first years."}]'::jsonb,
  null,
  array['technology', 'trivia', 'robotics', 'robots']::text[],
  3,
  'published',
  false,
  false,
  now()
)
