values (
  'es-trivia-robotica',
  'Trivia de robótica: de Unimate a los rovers de Marte',
  'Ocho preguntas sobre las máquinas que hicieron avanzar la robótica, del primer brazo industrial a los rovers de Marte.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"¿Qué máquina, instalada en una planta de General Motors en 1961, fue el primer robot industrial?","options":[{"id":"a","text":"PUMA","is_correct":false},{"id":"b","text":"Unimate","is_correct":true},{"id":"c","text":"Shakey","is_correct":false},{"id":"d","text":"AIBO","is_correct":false}],"explanation":"Unimate manipulaba piezas calientes de fundición a presión en la cadena de montaje de la planta de Ewing, Nueva Jersey."},{"id":"q2","question":"¿En qué obra de teatro de 1920 apareció por primera vez la palabra ''robot''?","options":[{"id":"a","text":"Metrópolis","is_correct":false},{"id":"b","text":"La guerra de los mundos","is_correct":false},{"id":"c","text":"R.U.R. (Los robots universales de Rossum)","is_correct":true},{"id":"d","text":"Frankenstein","is_correct":false}],"explanation":"La obra de Karel Čapek tomó el nombre de ''robota'', trabajo forzado en checo."},{"id":"q3","question":"¿Qué relato de Isaac Asimov de 1942 introdujo las Tres Leyes de la Robótica?","options":[{"id":"a","text":"''Runaround''","is_correct":true},{"id":"b","text":"''Robbie''","is_correct":false},{"id":"c","text":"''Las bóvedas de acero''","is_correct":false},{"id":"d","text":"''El conflicto evitable''","is_correct":false}],"explanation":"Asimov enunció las tres leyes explícitamente en ''Runaround'', recogido luego en ''Yo, robot''."},{"id":"q4","question":"¿Qué robot humanoide de Honda, presentado en 2000, podía caminar, correr y subir escaleras?","options":[{"id":"a","text":"Atlas","is_correct":false},{"id":"b","text":"Pepper","is_correct":false},{"id":"c","text":"QRIO","is_correct":false},{"id":"d","text":"ASIMO","is_correct":true}],"explanation":"ASIMO, fruto de más de una década de investigación de Honda, se desplazaba sobre dos piernas."},{"id":"q5","question":"¿Qué rover de la NASA explora el cráter Gale de Marte desde 2012?","options":[{"id":"a","text":"Curiosity","is_correct":true},{"id":"b","text":"Sojourner","is_correct":false},{"id":"c","text":"Opportunity","is_correct":false},{"id":"d","text":"Perseverance","is_correct":false}],"explanation":"Curiosity aterrizó en agosto de 2012 con la maniobra de la grúa volante y sigue operando."},{"id":"q6","question":"¿Qué rover aterrizó en Marte en 2021 llevando el helicóptero Ingenuity?","options":[{"id":"a","text":"Spirit","is_correct":false},{"id":"b","text":"Perseverance","is_correct":true},{"id":"c","text":"Curiosity","is_correct":false},{"id":"d","text":"Sojourner","is_correct":false}],"explanation":"Perseverance se posó en el cráter Jezero; Ingenuity realizó el primer vuelo propulsado en otro planeta."},{"id":"q7","question":"¿Qué sistema robótico, autorizado por la FDA en 2000, asiste a los cirujanos en el quirófano?","options":[{"id":"a","text":"AESOP","is_correct":false},{"id":"b","text":"ZEUS","is_correct":false},{"id":"c","text":"Sistema quirúrgico da Vinci","is_correct":true},{"id":"d","text":"Mako","is_correct":false}],"explanation":"El sistema da Vinci traduce los movimientos de las manos del cirujano en movimientos precisos de los instrumentos."},{"id":"q8","question":"¿Qué robot aspirador de iRobot, lanzado en 2002, se convirtió en un nombre familiar?","options":[{"id":"a","text":"Roomba","is_correct":true},{"id":"b","text":"Scooba","is_correct":false},{"id":"c","text":"Trilobite","is_correct":false},{"id":"d","text":"Neato","is_correct":false}],"explanation":"Roomba llevó los robots domésticos a millones de hogares y vendió más de un millón de unidades en sus primeros años."}]'::jsonb,
  null,
  array['tecnología', 'trivia', 'robótica', 'robots']::text[],
