insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-smartphone-history-trivia',
  'Smartphone History Trivia: From IBM Simon to iPhone',
  'Eight questions on the history of the smartphone, from IBM Simon and the Nokia 3310 to the iPhone and Android.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"Which 1994 device is regarded as the first smartphone?","options":[{"id":"a","text":"Nokia 9000 Communicator","is_correct":false},{"id":"b","text":"IBM Simon","is_correct":true},{"id":"c","text":"BlackBerry 850","is_correct":false},{"id":"d","text":"PalmPilot","is_correct":false}],"explanation":"The IBM Simon combined a phone with a touchscreen, email, calendar and apps."},{"id":"q2","question":"Who made the first call from a handheld mobile phone in 1973?","options":[{"id":"a","text":"Martin Cooper","is_correct":true},{"id":"b","text":"Steve Jobs","is_correct":false},{"id":"c","text":"Tim Berners-Lee","is_correct":false},{"id":"d","text":"Vint Cerf","is_correct":false}],"explanation":"Motorola engineer Martin Cooper called a rival at Bell Labs from a New York street."},{"id":"q3","question":"Which Nokia phone, released in 2000, became famous for the game Snake?","options":[{"id":"a","text":"Nokia 3210","is_correct":false},{"id":"b","text":"Nokia 8110","is_correct":false},{"id":"c","text":"Nokia 3310","is_correct":true},{"id":"d","text":"Nokia 5110","is_correct":false}],"explanation":"The 3310 sold about 126 million units and is remembered for its battery life and toughness."},{"id":"q4","question":"In which year did Apple introduce the first iPhone?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2008","is_correct":false},{"id":"c","text":"2010","is_correct":false},{"id":"d","text":"2007","is_correct":true}],"explanation":"Steve Jobs presented it in January 2007; it went on sale that June."},{"id":"q5","question":"Which was the first commercially sold Android phone, launched in 2008?","options":[{"id":"a","text":"HTC Dream (T-Mobile G1)","is_correct":true},{"id":"b","text":"Motorola Droid","is_correct":false},{"id":"c","text":"Samsung Galaxy S","is_correct":false},{"id":"d","text":"Nexus One","is_correct":false}],"explanation":"The HTC Dream, sold as the T-Mobile G1, shipped with Android 1.0 in October 2008."},{"id":"q6","question":"Which brand made its name with physical QWERTY keyboards and push email?","options":[{"id":"a","text":"Palm","is_correct":false},{"id":"b","text":"Sidekick","is_correct":false},{"id":"c","text":"BlackBerry","is_correct":true},{"id":"d","text":"HTC","is_correct":false}],"explanation":"BlackBerry devices dominated business messaging through the 2000s."},{"id":"q7","question":"Which operating system powered most Nokia smartphones before the Windows Phone era?","options":[{"id":"a","text":"Symbian","is_correct":true},{"id":"b","text":"MeeGo","is_correct":false},{"id":"c","text":"Series 40","is_correct":false},{"id":"d","text":"Windows Mobile","is_correct":false}],"explanation":"Nokia adopted Windows Phone in 2011; until then Symbian ran its smartphones."},{"id":"q8","question":"What did Steve Jobs say the iPhone combined when he unveiled it in 2007?","options":[{"id":"a","text":"A phone, a camera and a GPS","is_correct":false},{"id":"b","text":"An iPod, a phone and an internet communicator","is_correct":true},{"id":"c","text":"A computer, a pager and a fax","is_correct":false},{"id":"d","text":"A browser, a music player and a camera","is_correct":false}],"explanation":"''An iPod, a phone, and an internet communicator'' was the famous three-in-one pitch."}]'::jsonb,
  null,
  array['technology', 'trivia', 'smartphones', 'mobile phones']::text[],
  3,
  'published',
  false,
  false,
  now()
)
