smash","is_correct":false},{"id":"c","text":"Triller","is_correct":false},{"id":"d","text":"Musical.ly","is_correct":true}],"explanation":"Musical.ly''s users and lip-sync format moved into TikTok in August 2018."},{"id":"q7","question":"Which messaging app did Facebook acquire in 2014?","options":[{"id":"a","text":"WhatsApp","is_correct":true},{"id":"b","text":"Instagram","is_correct":false},{"id":"c","text":"Snapchat","is_correct":false},{"id":"d","text":"Telegram","is_correct":false}],"explanation":"Facebook bought WhatsApp for about 19 billion dollars; Instagram it had bought in 2012."},{"id":"q8","question":"Which platform popularized six-second looping videos before shutting down in 2017?","options":[{"id":"a","text":"Periscope","is_correct":false},{"id":"b","text":"Vine","is_correct":true},{"id":"c","text":"Myspace","is_correct":false},{"id":"d","text":"Google+","is_correct":false}],"explanation":"Vine''s looping six-second clips defined a short-video style later carried on by TikTok."}]'::jsonb,
