s_correct":false},{"id":"b","text":"Dubsmash","is_correct":false},{"id":"c","text":"Triller","is_correct":false},{"id":"d","text":"Musical.ly","is_correct":true}],"explanation":"Los usuarios y el formato de Musical.ly pasaron a TikTok en agosto de 2018."},{"id":"q7","question":"¿Qué aplicación de mensajería compró Facebook en 2014?","options":[{"id":"a","text":"WhatsApp","is_correct":true},{"id":"b","text":"Instagram","is_correct":false},{"id":"c","text":"Snapchat","is_correct":false},{"id":"d","text":"Telegram","is_correct":false}],"explanation":"Facebook pagó unos 19.000 millones de dólares por WhatsApp; a Instagram la había comprado en 2012."},{"id":"q8","question":"¿Qué plataforma popularizó los videos en bucle de seis segundos antes de cerrar en 2017?","options":[{"id":"a","text":"Periscope","is_correct":false},{"id":"b","text":"Vine","is_correct":true},{"id":"c","text":"Myspace","is_correct":false},{"id":"d","text":"Google+","is_correct":false}],"explanation":"Los clips de seis segundos de Vine definieron un estilo de video corto que luego continuó TikTok."}]'::jsonb,
