insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-gadgets-that-changed-the-world-trivia',
  'Gadgets Trivia: The Devices That Changed Everything',
  'Eight questions on the gadgets that changed daily life: the Walkman, Game Boy, iPod, Kindle, GPS and more.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"Which Sony cassette player, launched in 1979, made music portable?","options":[{"id":"a","text":"Discman","is_correct":false},{"id":"b","text":"MiniDisc","is_correct":false},{"id":"c","text":"Walkman","is_correct":true},{"id":"d","text":"Boombox","is_correct":false}],"explanation":"The Walkman TPS-L2 let people listen to tapes on headphones anywhere."},{"id":"q2","question":"Which Nintendo handheld console launched in 1989 bundled with Tetris?","options":[{"id":"a","text":"Game Boy","is_correct":true},{"id":"b","text":"Game Gear","is_correct":false},{"id":"c","text":"Lynx","is_correct":false},{"id":"d","text":"Game & Watch","is_correct":false}],"explanation":"The Game Boy''s battery life and Tetris bundle made it a runaway success."},{"id":"q3","question":"Which Apple device launched in 2001 promising ''1,000 songs in your pocket''?","options":[{"id":"a","text":"iPhone","is_correct":false},{"id":"b","text":"iPod","is_correct":true},{"id":"c","text":"iMac","is_correct":false},{"id":"d","text":"iPad","is_correct":false}],"explanation":"The first iPod held about 1,000 songs on its 5 GB hard drive."},{"id":"q4","question":"Which Amazon e-reader launched in 2007?","options":[{"id":"a","text":"Nook","is_correct":false},{"id":"b","text":"Kobo","is_correct":false},{"id":"c","text":"Kindle","is_correct":true},{"id":"d","text":"Sony Reader","is_correct":false}],"explanation":"The first Kindle sold out within hours and put e-books into the mainstream."},{"id":"q5","question":"What do the letters GPS stand for?","options":[{"id":"a","text":"Global Positioning System","is_correct":true},{"id":"b","text":"General Positioning Satellite","is_correct":false},{"id":"c","text":"Global Pathfinding Service","is_correct":false},{"id":"d","text":"Geographic Position System","is_correct":false}],"explanation":"The United States built GPS as a military system and opened it to civilian use."},{"id":"q6","question":"Which 1983 Motorola handset was the first commercially available handheld cell phone?","options":[{"id":"a","text":"MicroTAC","is_correct":false},{"id":"b","text":"DynaTAC 8000X","is_correct":true},{"id":"c","text":"StarTAC","is_correct":false},{"id":"d","text":"Razr","is_correct":false}],"explanation":"The DynaTAC 8000X weighed almost 800 grams and offered about 30 minutes of talk time."},{"id":"q7","question":"In which year did the first Apple Watch go on sale?","options":[{"id":"a","text":"2013","is_correct":false},{"id":"b","text":"2014","is_correct":false},{"id":"c","text":"2015","is_correct":true},{"id":"d","text":"2016","is_correct":false}],"explanation":"Announced in September 2014, the Apple Watch went on sale in April 2015."},{"id":"q8","question":"Which company launched the first mass-market consumer drone under the Phantom name in 2013?","options":[{"id":"a","text":"Parrot","is_correct":false},{"id":"b","text":"GoPro","is_correct":false},{"id":"c","text":"3D Robotics","is_correct":false},{"id":"d","text":"DJI","is_correct":true}],"explanation":"The DJI Phantom brought ready-to-fly camera drones to a general audience."}]'::jsonb,
  null,
  array['technology', 'trivia', 'gadgets', 'devices']::text[],
  3,
  'published',
